    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or visited[r][c]:
                continue
            stack = [(r, c)]
            visited[r][c] = True
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and not visited[nx][ny] and grid[nx][ny] == color:
                        visited[nx][ny] = True
                        stack.append((nx, ny))
            components.append((color, cells))
    out = [[0] * w for _ in range(h)]
