def solve(grid):
    H = len(grid)
    W = len(grid[0])
    zero_rows = [r for r in range(H) if all(grid[r][c] == 0 for c in range(W))]
    top_end = zero_rows[0]
    bottom_start = zero_rows[-1] + 1
    zero_cols = [c for c in range(W) if all(grid[r][c] == 0 for r in range(H))]
    left_end = zero_cols[0]
    right_start = zero_cols[-1] + 1
    def subgrid(r0, r1, c0, c1):
        return [row[c0:c1] for row in grid[r0:r1]]
    quadrants = [
        subgrid(0, top_end, 0, left_end),                       
        subgrid(0, top_end, right_start, W),                     
        subgrid(bottom_start, H, 0, left_end),                     
        subgrid(bottom_start, H, right_start, W),                   
    ]
    def signature(g):
        colors = sorted({v for row in g for v in row if v != 0})
        return tuple(colors)
    sigs = [signature(q) for q in quadrants]
    for i, s in enumerate(sigs):
        if sigs.count(s) == 1:
            return quadrants[i]
    def dominant_color(g):
        counts = {}
        for row in g:
            for v in row:
                if v != 0:
                    counts[v] = counts.get(v, 0) + 1
        if not counts:
            return 0
        return max(counts, key=counts.get)
    doms = [dominant_color(q) for q in quadrants]
    for i, d in enumerate(doms):
        if doms.count(d) == 1:
            return quadrants[i]
    return quadrants[0]

