def solve(grid):
    n = len(grid)
    m = len(grid[0])
    best_key = None
    best = None
    fallback_key = None
    fallback = None
    for pr in range(1, n + 1):
        for pc in range(1, m + 1):
            vals = [[None for _ in range(pc)] for _ in range(pr)]
            ok = True
            filled_classes = 0
            for i in range(n):
                for j in range(m):
                    v = grid[i][j]
                    if v == 0:
                        continue
                    r, c = i % pr, j % pc
                    if vals[r][c] is None:
                        vals[r][c] = v
                        filled_classes += 1
                    elif vals[r][c] != v:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue
            if filled_classes == pr * pc:
                key = (pr * pc, pr + pc, max(pr, pc), pr, pc)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (pr, pc, vals)
            miss = pr * pc - filled_classes
            key = (miss, pr * pc, pr + pc, max(pr, pc), pr, pc)
            if fallback_key is None or key < fallback_key:
                fallback_key = key
                fallback = (pr, pc, vals)
    if best is None:
        best = fallback
    pr, pc, vals = best
    out = []
    for i in range(n):
        row = []
        for j in range(m):
            v = vals[i % pr][j % pc]
            row.append(grid[i][j] if v is None else v)
        out.append(row)
    return out

def solve(grid):
    from collections import Counter, defaultdict, deque
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not seen[r][c]:
                q = deque([(r, c)])
                seen[r][c] = True
                comp = []
                while q:
                    x, y = q.popleft()
                    comp.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != 0 and not seen[nx][ny]:
                            seen[nx][ny] = True
                            q.append((nx, ny))
                components.append(comp)
    templates = []
    template_cells = set()
    for comp in components:
        colors = [grid[r][c] for r, c in comp]
        cnt = Counter(colors)
        singles = [col for col, k in cnt.items() if k == 1]
        repeated = [col for col, k in cnt.items() if k > 1]
        if len(comp) > 3 and len(singles) == 3 and len(repeated) == 1:
            marker_pos = {}
            for r, c in comp:
                col = grid[r][c]
                if cnt[col] == 1:
                    marker_pos[col] = (r, c)
            templates.append({
                "cells": [(r, c, grid[r][c]) for r, c in comp],
                "markers": marker_pos,
            })
            for rc in comp:
                template_cells.add(rc)
    remaining_by_color = defaultdict(set)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in template_cells:
                remaining_by_color[grid[r][c]].add((r, c))
    def transforms(dr, dc):
        return [
            (dr, dc),                
            (-dc, dr),             
            (-dr, -dc),             
            (dc, -dr),              
            (dr, -dc),                       
            (-dr, dc),                         
            (dc, dr),                             
            (-dc, -dr),                           
        ]
    out = [[0] * w for _ in range(h)]
    for tmpl in templates:
        marker_colors = sorted(tmpl["markers"].keys())
        anchor_color = marker_colors[0]
        ar, ac = tmpl["markers"][anchor_color]
        rel_cells = [(r - ar, c - ac, col) for r, c, col in tmpl["cells"]]
        rel_markers = {col: (r - ar, c - ac) for col, (r, c) in tmpl["markers"].items()}
        matched = False
        if anchor_color not in remaining_by_color:
            continue
        for t_idx in range(8):
            t_marker_rel = {}
            for col, (dr, dc) in rel_markers.items():
                t_marker_rel[col] = transforms(dr, dc)[t_idx]
            for tar_anchor in list(remaining_by_color[anchor_color]):
                tr, tc = tar_anchor
                used_positions = {anchor_color: tar_anchor}
                ok = True
                for col in marker_colors:
                    dr, dc = t_marker_rel[col]
                    pos = (tr + dr, tc + dc)
                    if not (0 <= pos[0] < h and 0 <= pos[1] < w):
                        ok = False
                        break
                    if pos not in remaining_by_color[col]:
                        ok = False
                        break
                    used_positions[col] = pos
                if not ok:
                    continue
                for dr, dc, col in rel_cells:
                    tdr, tdc = transforms(dr, dc)[t_idx]
                    rr, cc = tr + tdr, tc + tdc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = col
                for col, pos in used_positions.items():
                    if pos in remaining_by_color[col]:
                        remaining_by_color[col].remove(pos)
                matched = True
                break
            if matched:
                break
    return out

