    maxr = max(r for r, c in nz)
    minc = min(c for r, c in nz)
    maxc = max(c for r, c in nz)
    if sr == minr:
        dr, dc = 1, 0                                         
    elif sr == maxr:
        dr, dc = -1, 0                                         
    elif sc == minc:
        dr, dc = 0, 1                                       
    elif sc == maxc:
        dr, dc = 0, -1                                      
    else:
        d_top = sr - minr
        d_bottom = maxr - sr
        d_left = sc - minc
        d_right = maxc - sc
        side = min(
            [('top', d_top), ('bottom', d_bottom), ('left', d_left), ('right', d_right)],
            key=lambda x: x[1]
        )[0]
        if side == 'top':
            dr, dc = 1, 0
        elif side == 'bottom':
            dr, dc = -1, 0
        elif side == 'left':
