    start = 0
    for r in sep_rows:
        if start < r:
            r_intervals.append((start, r - 1))
        start = r + 1
    if start < H:
        r_intervals.append((start, H - 1))
    c_intervals = []
    start = 0
    for c in sep_cols:
        if start < c:
            c_intervals.append((start, c - 1))
        start = c + 1
    if start < W:
        c_intervals.append((start, W - 1))
    object_color = None
    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            if val != 0 and val != 5:
                object_color = val
                break
        if object_color is not None:
            break
    if object_color is None:
        res = [[0]*W for _ in range(H)]
        for r in sep_rows:
            for c in range(W): res[r][c] = 5
        for c in sep_cols:
            for r in range(H): res[r][c] = 5
        return res
    region_data = []
    for r_start, r_end in r_intervals:
        for c_start, c_end in c_intervals:
            count = 0
            for r in range(r_start, r_end + 1):
                for c in range(c_start, c_end + 1):
                    if grid[r][c] == object_color:
                        count += 1
            region_data.append({
                'r_start': r_start, 'r_end': r_end,
                'c_start': c_start, 'c_end': c_end,
                'count': count
            })
    max_count = 0
    if region_data:
        max_count = max(rd['count'] for rd in region_data)
    output = [[0 for _ in range(W)] for _ in range(H)]
    for r in sep_rows:
        for c in range(W):
            output[r][c] = 5
    for c in sep_cols:
        for r in range(H):
            output[r][c] = 5
    for rd in region_data:
        if rd['count'] == max_count:
            for r in range(rd['r_start'], rd['r_end'] + 1):
                for c in range(rd['c_start'], rd['c_end'] + 1):
                    output[r][c] = object_color
