    for rs in range(n):
        for cs in range(n):
            score = 0
            for r, c, v in nonzero:
                pred = (((r + rs) % n) * ((c + cs) % n)) % n + 1
                if pred == v:
                    score += 1
            if score > best_score:
                best_score = score
                best_rs, best_cs = rs, cs
    rs, cs = best_rs, best_cs
    return [
        [(((r + rs) % n) * ((c + cs) % n)) % n + 1 for c in range(w)]
        for r in range(h)
    ]

