def solve(grid):
    from collections import Counter, deque
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            seen[r][c] = True
            color = g[r][c]
            q = deque([(r, c)])
            cells = [(r, c)]
            while q:
                x, y = q.popleft()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and not seen[nx][ny] and g[nx][ny] == color:
                        seen[nx][ny] = True
                        q.append((nx, ny))
                        cells.append((nx, ny))
            components.append((color, cells))
    rect = None
    rect_cells = set()
    best_area = -1
    for color, cells in components:
        if color == bg or len(cells) <= 1:
            continue
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        area = (r1 - r0 + 1) * (c1 - c0 + 1)
        if area == len(cells) and area > best_area:
            best_area = area
            rect = (color, r0, r1, c0, c1)
            rect_cells = set(cells)
    if rect is None:
        return g
    rect_color, r0, r1, c0, c1 = rect
    for r in range(h):
        for c in range(w):
            if (r, c) in rect_cells:
                continue
            color = g[r][c]
            if color == bg:
                continue
            if r0 <= r <= r1:
                if c < c0:
                    for y in range(c + 1, c0):
                        if g[r][y] == bg:
                            g[r][y] = color
                elif c > c1:
                    for y in range(c1 + 1, c):
                        if g[r][y] == bg:
                            g[r][y] = color
            elif c0 <= c <= c1:
                if r < r0:
                    for x in range(r + 1, r0):
                        if g[x][c] == bg:
                            g[x][c] = color
                elif r > r1:
                    for x in range(r1 + 1, r):
                        if g[x][c] == bg:
                            g[x][c] = color
    return g

def solve(grid):
    rows, cols = len(grid), len(grid[0])
    sep_r = None
    sep_c = None
    uniform_rows = [i for i in range(rows) if len(set(grid[i])) == 1]
    uniform_cols = []
    for j in range(cols):
        col_vals = [grid[i][j] for i in range(rows)]
        if len(set(col_vals)) == 1:
            uniform_cols.append(j)
    for i in uniform_rows:
        color = grid[i][0]
        for j in uniform_cols:
            if grid[0][j] == color and all(grid[r][j] == color for r in range(rows)):
                sep_r, sep_c = i, j
                break
        if sep_r is not None:
            break
    if sep_r is None or sep_c is None:
        return grid
    counts = {}
    for i in range(rows):
        if i == sep_r:
            continue
        for j in range(cols):
            if j == sep_c:
                continue
            v = grid[i][j]
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    quads = [
        [row[:sep_c] for row in grid[:sep_r]],                    
        [row[sep_c+1:] for row in grid[:sep_r]],                   
        [row[:sep_c] for row in grid[sep_r+1:]],                     
        [row[sep_c+1:] for row in grid[sep_r+1:]],                    
    ]
    def score(q):
        return sum(1 for row in q for v in row if v != background)
    best_quad = max(quads, key=score)
    return best_quad

def solve(grid):
    H, W = len(grid), len(grid[0])
    def inb(r, c):
        return 0 <= r < H and 0 <= c < W
    def find_cells(color):
        return [(r, c) for r in range(H) for c in range(W) if grid[r][c] == color]
    def get_bar_info(color):
        cells = find_cells(color)
        if not cells:
            return None
        rows = sorted(set(r for r, c in cells))
        cols = sorted(set(c for r, c in cells))
        if len(rows) == 1:                  
            r = rows[0]
            cs = sorted(c for _, c in cells)
            return {
                "ori": "h",
                "cells": cells,
                "ends": [((r, cs[0]), (0, -1)), ((r, cs[-1]), (0, 1))],
                "center": (sum(r for r, c in cells) / len(cells), sum(c for r, c in cells) / len(cells)),
            }
        else:                
            c = cols[0]
            rs = sorted(r for r, _ in cells)
            return {
                "ori": "v",
                "cells": cells,
                "ends": [((rs[0], c), (-1, 0)), ((rs[-1], c), (1, 0))],
                "center": (sum(r for r, c in cells) / len(cells), sum(c for r, c in cells) / len(cells)),
            }
    def extend_from(endpoint, d):
        r, c = endpoint[0] + d[0], endpoint[1] + d[1]
        if not inb(r, c) or grid[r][c] != 0:
            return None
        cells = []
        while inb(r, c) and grid[r][c] == 0:
            cells.append((r, c))
            nr, nc = r + d[0], c + d[1]
            if not inb(nr, nc) or grid[nr][nc] != 0:
                break
            r, c = nr, nc
        return cells
    def line_cells(a, b):
        r1, c1 = a
        r2, c2 = b
        out = []
        if r1 == r2:
            step = 1 if c2 > c1 else -1
            for c in range(c1 + step, c2 + step, step):
                out.append((r1, c))
        elif c1 == c2:
            step = 1 if r2 > r1 else -1
            for r in range(r1 + step, r2 + step, step):
                out.append((r, c1))
        return out
    def clear(cells):
        return all(inb(r, c) and grid[r][c] == 0 for r, c in cells)
    def build_route(pivot, target_adj, source_ori):
        pr, pc = pivot
        tr, tc = target_adj
        if source_ori == "v":
            if pc == tc:
                return None
            mid = (pr, tc)
            seg2 = line_cells((pr, pc), mid)
            seg3 = line_cells(mid, (tr, tc))
        else:
            if pr == tr:
                return None
            mid = (tr, pc)
            seg2 = line_cells((pr, pc), mid)
            seg3 = line_cells(mid, (tr, tc))
        route = seg2 + seg3
        if clear(route):
            return route
        return None
    src = get_bar_info(3)
    dst = get_bar_info(2)
    if src is None or dst is None:
        return [row[:] for row in grid]
    best_path = None
    best_key = None
    sr_center, sc_center = src["center"]
    tr_center, tc_center = dst["center"]
    for endpoint, d in src["ends"]:
        ext = extend_from(endpoint, d)
        if not ext:
            continue
        pivot = ext[-1]
        if src["ori"] == "v":
            toward = -1 if tr_center < sr_center else 1
            dir_pref = 0 if d[0] == toward else 1
        else:
            toward = -1 if tc_center < sc_center else 1
            dir_pref = 0 if d[1] == toward else 1
        for dst_endpoint, dst_d in dst["ends"]:
            q = (dst_endpoint[0] + dst_d[0], dst_endpoint[1] + dst_d[1])
            if not inb(*q) or grid[q[0]][q[1]] != 0:
                continue
            route = build_route(pivot, q, src["ori"])
            if route is None:
                continue
            path = ext + route
            key = (len(path), dir_pref)
            if best_key is None or key < best_key:
                best_key = key
                best_path = path
    out = [row[:] for row in grid]
    if best_path is not None:
        for r, c in best_path:
            out[r][c] = 3
    return out

