    ph, pw = rmax - rmin + 1, cmax - cmin + 1
    pattern = [[0] * pw for _ in range(ph)]
    mask = [[False] * pw for _ in range(ph)]
    for r, c in src_cells:
        pattern[r - rmin][c - cmin] = grid[r][c]
        mask[r - rmin][c - cmin] = True
    visited = [[False] * w for _ in range(h)]
    out = [[0] * w for _ in range(h)]
    def neighbors(r, c):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                yield nr, nc
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                comp = []
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for nr, nc in neighbors(cr, cc):
                        if grid[nr][nc] == 8 and not visited[nr][nc]:
                            visited[nr][nc] = True
