                rrmin = min(x for x, y in comp)
                rrmax = max(x for x, y in comp)
                ccmin = min(y for x, y in comp)
                ccmax = max(y for x, y in comp)
                ch, cw = rrmax - rrmin + 1, ccmax - ccmin + 1
