    def detect_offset_rows():
        best_k = 0
        best_mism = None
        best_comp = -1
        for k in range(n):
            mism = 0
            comp = 0
            for r in range(k, n):
                rp = n + k - 1 - r
                if not (k <= rp < n):
                    continue
                if r >= rp:
                    continue
                row_a = grid[r]
                row_b = grid[rp]
                for c in range(m):
                    a = row_a[c]
                    b = row_b[c]
                    if a != 9 and b != 9:
                        comp += 1
                        if a != b:
                            mism += 1
            if comp == 0:
                continue
            score = (mism, -comp)
            if best_mism is None or score < best_mism:
                best_mism = score
                best_k = k
        return best_k
    def detect_offset_cols():
        best_k = 0
        best_mism = None
        best_comp = -1
        for k in range(m):
            mism = 0
            comp = 0
            for c in range(k, m):
                cp = m + k - 1 - c
                if not (k <= cp < m):
                    continue
                if c >= cp:
                    continue
                for r in range(n):
                    a = grid[r][c]
                    b = grid[r][cp]
                    if a != 9 and b != 9:
                        comp += 1
                        if a != b:
                            mism += 1
            if comp == 0:
                continue
            score = (mism, -comp)
            if best_mism is None or score < best_mism:
                best_mism = score
                best_k = k
        return best_k
    kr = detect_offset_rows()
    kc = detect_offset_cols()
    out = [row[:] for row in grid]
    def orbit(r, c):
        rs = {r}
        cs = {c}
        if r >= kr:
            rp = n + kr - 1 - r
            if 0 <= rp < n:
                rs.add(rp)
        if c >= kc:
            cp = m + kc - 1 - c
            if 0 <= cp < m:
                cs.add(cp)
        pts = []
        for rr in rs:
            for cc in cs:
                pts.append((rr, cc))
        pts.sort()
        return pts
    visited = set()
    for r in range(n):
        for c in range(m):
            if (r, c) in visited:
                continue
            pts = orbit(r, c)
            for p in pts:
                visited.add(p)
            vals = []
            for rr, cc in pts:
                v = out[rr][cc]
