def solve(grid):
    from collections import deque, defaultdict
    H = len(grid)
    W = len(grid[0]) if H else 0
    out = [row[:] for row in grid]
    def bfs_components():
        vis = [[False] * W for _ in range(H)]
        comps = []
        for r in range(H):
            for c in range(W):
                if grid[r][c] == 0 or vis[r][c]:
                    continue
                q = deque([(r, c)])
                vis[r][c] = True
                cells = []
                by_color = defaultdict(list)
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    by_color[grid[x][y]].append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and not vis[nx][ny] and grid[nx][ny] != 0:
                            vis[nx][ny] = True
                            q.append((nx, ny))
                comps.append({
                    "cells": cells,
                    "colors": set(by_color.keys()),
                    "by_color": dict(by_color),
                })
        return comps
    def bbox(cells):
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        return min(rs), max(rs), min(cs), max(cs)
    def square_info(cells):
        r0, r1, c0, c1 = bbox(cells)
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if h == w and h * w == len(cells):
            return r0, c0, h
        return None
    def tile_offsets(color_cells, anchor_r, anchor_c, size):
        groups = defaultdict(int)
        for r, c in color_cells:
            dr = (r - anchor_r) // size
            dc = (c - anchor_c) // size
            groups[(dr, dc)] += 1
        return {pos for pos, cnt in groups.items() if cnt == size * size}
    comps = bfs_components()
    two_color_ids = [i for i, comp in enumerate(comps) if len(comp["colors"]) == 2]
    color_to_comps = defaultdict(list)
    for i in two_color_ids:
        for col in comps[i]["colors"]:
            color_to_comps[col].append(i)
    candidates = []
    for i in two_color_ids:
        comp = comps[i]
        cols = list(comp["colors"])
        for k in cols:
            if len(color_to_comps[k]) <= 1:
                continue
            p = cols[0] if cols[1] == k else cols[1]
            kinfo = square_info(comp["by_color"][k])
            if kinfo is None:
                continue
            kr, kc, ks = kinfo
            offsets = tile_offsets(comp["by_color"][p], kr, kc, ks)
            if len(offsets) > 1:
                candidates.append((len(offsets), i, k, p, offsets, ks))
    if not candidates:
        return out
    candidates.sort(reverse=True)
    _, exemplar_id, key_color, pattern_color, template_offsets, _ = candidates[0]
    for i in color_to_comps[key_color]:
        if i == exemplar_id:
            continue
        comp = comps[i]
        other_colors = [c for c in comp["colors"] if c != key_color]
        if len(other_colors) != 1:
            continue
        fill_color = other_colors[0]
        kinfo = square_info(comp["by_color"][key_color])
        if kinfo is None:
            continue
        kr, kc, ks = kinfo
        for dr, dc in template_offsets:
            r0 = kr + dr * ks
            c0 = kc + dc * ks
            if not (0 <= r0 and 0 <= c0 and r0 + ks <= H and c0 + ks <= W):
                continue
            for rr in range(r0, r0 + ks):
                for cc in range(c0, c0 + ks):
                    if out[rr][cc] == 0 or out[rr][cc] == fill_color:
                        out[rr][cc] = fill_color
    return out

def solve(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])
    cnt = Counter()
    for row in grid:
        for v in row:
            if v != 0:
                cnt[v] += 1
    colors = list(cnt.keys())
    def analyze_color(c):
        pos = [(r, col) for r in range(H) for col in range(W) if grid[r][col] == c]
        if not pos:
            return None
        r0 = min(r for r, _ in pos)
        r1 = max(r for r, _ in pos)
        c0 = min(col for _, col in pos)
        c1 = max(col for _, col in pos)
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if h % 3 != 0 or w % 3 != 0:
            return None
        bh = h // 3
        bw = w // 3
        pattern = [[0] * 3 for _ in range(3)]
        total = 0
        for i in range(3):
            for j in range(3):
                n = 0
                for r in range(r0 + i * bh, r0 + (i + 1) * bh):
                    for col in range(c0 + j * bw, c0 + (j + 1) * bw):
                        if grid[r][col] == c:
                            n += 1
                if n == bh * bw:
                    pattern[i][j] = 1
                    total += n
                elif n == 0:
                    pass
                else:
                    return None                                     
        if total != cnt[c]:
            return None
        return {
            "color": c,
            "bbox": (r0, r1, c0, c1),
            "pattern": pattern,
            "count": cnt[c],
        }
    candidates = []
    for c in colors:
        info = analyze_color(c)
        if info is not None:
            candidates.append(info)
    if candidates:
        obj = max(candidates, key=lambda x: x["count"])
        obj_color = obj["color"]
        pattern = obj["pattern"]
    else:
        obj_color = max(colors, key=lambda c: cnt[c])
        pos = [(r, col) for r in range(H) for col in range(W) if grid[r][col] == obj_color]
        r0 = min(r for r, _ in pos)
        r1 = max(r for r, _ in pos)
        c0 = min(col for _, col in pos)
        c1 = max(col for _, col in pos)
        bh = (r1 - r0 + 1) // 3
        bw = (c1 - c0 + 1) // 3
        pattern = [[0] * 3 for _ in range(3)]
        for i in range(3):
            for j in range(3):
                found = False
                for r in range(r0 + i * bh, r0 + (i + 1) * bh):
                    for col in range(c0 + j * bw, c0 + (j + 1) * bw):
                        if grid[r][col] == obj_color:
                            found = True
                pattern[i][j] = 1 if found else 0
    other_colors = [c for c in colors if c != obj_color]
    out_color = min(other_colors, key=lambda c: cnt[c]) if other_colors else obj_color
    return [[out_color if pattern[i][j] else 0 for j in range(3)] for i in range(3)]

