    pts.sort()                         
    (r1, c1), (r2, c2), (r3, c3) = pts
    dr1, dc1 = r2 - r1, c2 - c1
    dr2, dc2 = r3 - r2, c3 - c2
    if (dr1, dc1) != (dr2, dc2):
        return [row[:] for row in grid]
    d = abs(dr1)
    same_diag = (dc1 == dr1)                                                      
    anti_diag = (dc1 == -dr1)                                                     
    if not (same_diag or anti_diag):
        return [row[:] for row in grid]
    out = [[0 for _ in range(w)] for _ in range(h)]
    def draw_square(top, left, bottom, right):
        if 0 <= top < h:
            for c in range(max(0, left), min(w - 1, right) + 1):
                out[top][c] = color
        if 0 <= bottom < h:
            for c in range(max(0, left), min(w - 1, right) + 1):
