                out[r][left] = color
        if 0 <= right < w:
            for r in range(max(0, top), min(h - 1, bottom) + 1):
                out[r][right] = color
    k = -1
    while True:
        if same_diag:
            top = r1 - k * d
            left = c1 - k * d
            bottom = r3 + k * d
            right = c3 + k * d
        else:
            top = r1 - k * d
            right = c1 + k * d
            bottom = r3 + k * d
            left = c3 - k * d
