                        cur = canvas[rr][cc]
                        if cur != 0 and cur != v:
                            for x, y in changed:
                                canvas[x][y] = 0
                            return None
                        if cur == 0:
                            canvas[rr][cc] = v
                            changed.append((rr, cc))
                return changed
            def unplace(changed):
                for x, y in changed:
                    canvas[x][y] = 0
            def dfs(k, filled):
                nonlocal best_canvas, best_score
                if k == len(shapes):
                    zeros = H * W - filled
                    score = (zeros, H * W, H + W)
                    if best_score is None or score < best_score:
                        best_score = score
                        best_canvas = [row[:] for row in canvas]
                    return
                shape = shapes[k]
                h, w = len(shape), len(shape[0])
                for r in range(H - h + 1):
                    for c in range(W - w + 1):
                        changed = place(shape, r, c)
                        if changed is None:
                            continue
                        dfs(k + 1, filled + len(changed))
                        unplace(changed)
                        if best_score is not None and best_score[0] == 0 and best_score[1] == H * W:
                            return
            dfs(0, 0)
    try_sizes()
    return best_canvas

