    def find_components(target, allowed_rows=None):
        allowed = None if allowed_rows is None else set(allowed_rows)
        seen = [[False] * W for _ in range(H)]
        comps = []
        for r in range(H):
            if allowed is not None and r not in allowed:
                continue
            for c in range(W):
                if grid[r][c] != target or seen[r][c]:
                    continue
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if allowed is not None and nx not in allowed:
                                continue
                            if not seen[nx][ny] and grid[nx][ny] == target:
                                seen[nx][ny] = True
                                q.append((nx, ny))
                comps.append(cells)
        return comps
    def normalize(cells):
        minr = min(r for r, c in cells)
        maxr = max(r for r, c in cells)
        minc = min(c for r, c in cells)
        maxc = max(c for r, c in cells)
        norm = frozenset((r - minr, c - minc) for r, c in cells)
        return {
            "cells": norm,
            "minr": minr,
            "maxr": maxr,
            "minc": minc,
            "maxc": maxc,
            "h": maxr - minr + 1,
            "w": maxc - minc + 1,
        }
    top_rows = [r for r in range(H) if 2 in grid[r]]
    hole_comps = [normalize(cells) for cells in find_components(0, allowed_rows=top_rows)]
    bottom_raw = find_components(5)
