    for comp in bottom_raw:
        info = normalize(comp)
        full_cells = info["cells"]
        h = info["h"]
        variants = []
        for k in range(1, h + 1):
            prefix = [(r, c) for (r, c) in full_cells if r < k]
            if not prefix:
                continue
            minc_pref = min(c for r, c in prefix)
            norm_pref = frozenset((r, c - minc_pref) for r, c in prefix)
            variants.append({
                "prefix": norm_pref,
                "offset_c": minc_pref,                                                            
            })
        bottom_shapes.append({
            "full_cells": full_cells,
            "h": h,
            "w": info["w"],
            "variants": variants,
        })
    options = []
    for hi, hole in enumerate(hole_comps):
        hole_opts = []
        for bi, shape in enumerate(bottom_shapes):
            for var in shape["variants"]:
                if var["prefix"] == hole["cells"]:
                    anchor_r = hole["minr"]
                    anchor_c = hole["minc"] - var["offset_c"]
                    ok = True
                    for r, c in shape["full_cells"]:
                        rr, cc = anchor_r + r, anchor_c + c
                        if not (0 <= rr < H and 0 <= cc < W):
                            ok = False
                            break
                    if ok:
                        hole_opts.append((bi, anchor_r, anchor_c))
        options.append((hi, hole_opts))
    options.sort(key=lambda x: len(x[1]))
    assignment = {}
    def bt(i, used):
        if i == len(options):
            return True
        hi, opts = options[i]
        for bi, ar, ac in opts:
            if bi in used:
                continue
            assignment[hi] = (bi, ar, ac)
            used.add(bi)
            if bt(i + 1, used):
                return True
            used.remove(bi)
            del assignment[hi]
        return False
    bt(0, set())
    out = [row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            if out[r][c] == 5:
                out[r][c] = 0
