        for c in range(w):
            if grid[r][c] != 0 or visited[r][c]:
                continue
            stack = [(r, c)]
            visited[r][c] = True
            comp = []
            touches_edge = False
            enclosed = True
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                if x == 0 or x == h - 1 or y == 0 or y == w - 1:
                    touches_edge = True
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w:
                        if grid[nx][ny] == 0:
                            if not visited[nx][ny]:
                                visited[nx][ny] = True
                                stack.append((nx, ny))
                        else:
                            if grid[nx][ny] != 1:
                                enclosed = False
            if (not touches_edge) and enclosed:
                fill = 7 if (len(comp) % 2 == 1) else 2
                for x, y in comp:
                    out[x][y] = fill
    return out

def solve(grid):
    n, m = len(grid), len(grid[0])
    pref = [[[0] * (m + 1) for _ in range(n + 1)] for _ in range(10)]
    for color in range(10):
        p = pref[color]
        for i in range(n):
            run = 0
            for j in range(m):
                if grid[i][j] == color:
                    run += 1
                p[i + 1][j + 1] = p[i][j + 1] + run
    def rect_count(color, r1, c1, r2, c2):
        p = pref[color]
        return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1]
    def find_candidate(strict=True):
        best = None
        best_key = None
        for r1 in range(n):
            for r2 in range(r1, n):
                h = r2 - r1 + 1
                for c1 in range(m):
                    for c2 in range(c1, m):
                        w = c2 - c1 + 1
                        area = h * w
                        if best_key is not None and area < best_key[0]:
                            continue
                        counts = []
                        for color in range(10):
                            cnt = rect_count(color, r1, c1, r2, c2)
                            if cnt:
                                counts.append((cnt, color))
                                if len(counts) > 2:
                                    break
                        if len(counts) != 2:
                            continue
                        counts.sort(reverse=True)                  
                        dom_cnt, dom_color = counts[0]
                        min_cnt, min_color = counts[1]
                        if dom_cnt <= min_cnt:
                            continue
                        if strict:
                            if min_cnt > min(h, w):
                                continue
                        else:
                            if dom_cnt * 10 < area * 7:                         
                                continue
                        key = (area, dom_cnt, -min_cnt)
                        if best_key is None or key > best_key:
                            best_key = key
                            best = (r1, c1, r2, c2, dom_color, min_color)
        return best
    best = find_candidate(strict=True)
    if best is None:
        best = find_candidate(strict=False)
    r1, c1, r2, c2, main_color, mark_color = best
    h, w = r2 - r1 + 1, c2 - c1 + 1
    bad_rows = set()
    bad_cols = set()
    for i in range(h):
        for j in range(w):
            if grid[r1 + i][c1 + j] == mark_color:
                bad_rows.add(i)
                bad_cols.add(j)
    out = []
    for i in range(h):
        row = []
        for j in range(w):
            if i in bad_rows or j in bad_cols:
                row.append(mark_color)
            else:
                row.append(main_color)
        out.append(row)
    return out

