def solve(grid):
    from collections import Counter
    g = [row[:] for row in grid]
    n, m = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    def is_hollow_frame(r, c, h, w):
        color = g[r][c]
        if color == 0:
            return False
        for j in range(c, c + w):
            if g[r][j] != color or g[r + h - 1][j] != color:
                return False
        for i in range(r, r + h):
            if g[i][c] != color or g[i][c + w - 1] != color:
                return False
        for i in range(r + 1, r + h - 1):
            for j in range(c + 1, c + w - 1):
                if g[i][j] != 0:
                    return False
        return True
    best = None
    best_score = None
    for h in range(3, n + 1):
        for w in range(3, m + 1):
            border_cells = 2 * h + 2 * w - 4
            for r in range(n - h + 1):
                for c in range(m - w + 1):
                    if is_hollow_frame(r, c, h, w):
                        color = g[r][c]
                        exact_color_match = (counts[color] == border_cells)
                        score = (
                            1 if exact_color_match else 0,
                            h * w
                        )
                        if best is None or score > best_score:
                            best = (r, c, h, w, color)
                            best_score = score
    if best is None:
        return g
    sr, sc, h, w, color = best
    candidates = []
    for r in range(n - h + 1):
        for c in range(m - w + 1):
            if r == sr and c == sc:
                continue
            ok = True
            for i in range(r + 1, r + h - 1):
                for j in range(c + 1, c + w - 1):
                    if g[i][j] != 0:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                dist2 = (r - sr) * (r - sr) + (c - sc) * (c - sc)
                candidates.append((dist2, r, c))
    if not candidates:
        return g
    _, tr, tc = max(candidates)
    out = [row[:] for row in g]
    for j in range(tc, tc + w):
        out[tr][j] = color
        out[tr + h - 1][j] = color
    for i in range(tr, tr + h):
        out[i][tc] = color
        out[i][tc + w - 1] = color
    return out

def solve(grid):
    from math import gcd
    from collections import deque
    R, C = len(grid), len(grid[0])
    fours = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 4]
    minr = min(r for r, _ in fours)
    maxr = max(r for r, _ in fours)
    minc = min(c for _, c in fours)
    maxc = max(c for _, c in fours)
    H = maxr - minr + 1
    W = maxc - minc + 1
    crop = [row[minc:maxc + 1] for row in grid[minr:maxr + 1]]
    vis = [[False] * W for _ in range(H)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    sizes = []
    for r in range(H):
        for c in range(W):
            color = crop[r][c]
            if color in (0, 4) or vis[r][c]:
                continue
            q = deque([(r, c)])
            vis[r][c] = True
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W and not vis[nx][ny] and crop[nx][ny] == color:
                        vis[nx][ny] = True
                        q.append((nx, ny))
            rs = [x for x, _ in cells]
            cs = [y for _, y in cells]
            h = max(rs) - min(rs) + 1
            w = max(cs) - min(cs) + 1
            sizes.extend([h, w])
    s = 0
    for v in sizes:
        s = gcd(s, v)
    if s == 0:
        s = 1
    outside_pts = []
    for r in range(R):
        for c in range(C):
            if minr <= r <= maxr and minc <= c <= maxc:
                continue
            if grid[r][c] not in (0, 4):
                outside_pts.append((r, c, grid[r][c]))
    if not outside_pts:
        return crop
    tr0 = min(r for r, _, _ in outside_pts)
    tr1 = max(r for r, _, _ in outside_pts)
    tc0 = min(c for _, c, _ in outside_pts)
    tc1 = max(c for _, c, _ in outside_pts)
    th = tr1 - tr0 + 1
    tw = tc1 - tc0 + 1
    template = [[0] * tw for _ in range(th)]
    for r, c, v in outside_pts:
        template[r - tr0][c - tc0] = v
    existing = [(r, c, crop[r][c]) for r in range(H) for c in range(W) if crop[r][c] not in (0, 4)]
    marker_cells = [(r, c) for r in range(H) for c in range(W) if crop[r][c] == 4]
    found = None
    max_ro = H - th * s
    max_co = W - tw * s
    for ro in range(max_ro + 1):
        for co in range(max_co + 1):
            ok = True
            for r, c, v in existing:
                rr = r - ro
                cc = c - co
                if rr < 0 or cc < 0 or rr >= th * s or cc >= tw * s:
                    ok = False
                    break
                tv = template[rr // s][cc // s]
                if tv != v:
                    ok = False
                    break
            if not ok:
                continue
            for r, c in marker_cells:
                rr = r - ro
                cc = c - co
                if 0 <= rr < th * s and 0 <= cc < tw * s:
                    if template[rr // s][cc // s] != 0:
                        ok = False
                        break
            if ok:
                found = (ro, co)
                break
        if found is not None:
            break
    if found is None:
        return crop
    ro, co = found
    out = [[0] * W for _ in range(H)]
    for r, c in marker_cells:
        out[r][c] = 4
    for i in range(th):
        for j in range(tw):
            v = template[i][j]
            if v == 0:
                continue
            for dr in range(s):
                for dc in range(s):
                    out[ro + i * s + dr][co + j * s + dc] = v
    return out

