        while stack:
            r, c = stack.pop()
            cells.append((r, c))
            for nr, nc in neighbors(r, c):
                if not visited[nr][nc] and grid[nr][nc] == color:
                    visited[nr][nc] = True
                    stack.append((nr, nc))
        return color, cells
    def is_full_rectangle(cells):
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        r1, r2 = min(rs), max(rs)
        c1, c2 = min(cs), max(cs)
        return len(cells) == (r2 - r1 + 1) * (c2 - c1 + 1)
    def analyze_vertical(cells):
        row_map = {}
        for r, c in cells:
            row_map.setdefault(r, []).append(c)
        for r in row_map:
            row_map[r].sort()
        rect_rows = [r for r, cols in row_map.items() if len(cols) > 1]
        arm_rows = [r for r, cols in row_map.items() if len(cols) == 1]
        if not rect_rows or not arm_rows:
            return None
        rect_rows.sort()
        arm_rows.sort()
        rr1, rr2 = rect_rows[0], rect_rows[-1]
        if rect_rows != list(range(rr1, rr2 + 1)):
            return None
        c1 = min(row_map[rect_rows[0]])
        c2 = max(row_map[rect_rows[0]])
        if c2 - c1 + 1 <= 1:
            return None
        for r in rect_rows:
            cols = row_map[r]
            if cols[0] != c1 or cols[-1] != c2 or len(cols) != (c2 - c1 + 1):
                return None
        arm_cols = {row_map[r][0] for r in arm_rows}
        if len(arm_cols) != 1:
            return None
        arm_c = next(iter(arm_cols))
        if not (c1 <= arm_c <= c2):
            return None
        H = rr2 - rr1 + 1
        if arm_rows == list(range(arm_rows[0], arm_rows[-1] + 1)) and arm_rows[-1] == rr1 - 1:
            new_r1 = arm_rows[0]
            new_r2 = new_r1 + H - 1
            return (new_r1, new_r2, c1, c2)
        if arm_rows == list(range(arm_rows[0], arm_rows[-1] + 1)) and arm_rows[0] == rr2 + 1:
            new_r2 = arm_rows[-1]
            new_r1 = new_r2 - H + 1
            return (new_r1, new_r2, c1, c2)
        return None
    def analyze_horizontal(cells):
