def solve(grid):
    from collections import deque, defaultdict
    H, W = len(grid), len(grid[0])
    def neighbors4(r, c):
        if r > 0:
            yield r - 1, c
        if r + 1 < H:
            yield r + 1, c
        if c > 0:
            yield r, c - 1
        if c + 1 < W:
            yield r, c + 1
    color_positions = defaultdict(list)
    for r in range(H):
        for c in range(W):
            color_positions[grid[r][c]].append((r, c))
    isolated_candidates = []
    for color, positions in color_positions.items():
        isolated = True
        for r, c in positions:
            for nr, nc in neighbors4(r, c):
                if grid[nr][nc] == color:
                    isolated = False
                    break
            if not isolated:
                break
        if isolated:
            isolated_candidates.append(color)
    if isolated_candidates:
        marker_color = min(isolated_candidates, key=lambda c: len(color_positions[c]))
    else:
        marker_color = min(color_positions, key=lambda c: len(color_positions[c]))
    comp_id = [[-1] * W for _ in range(H)]
    comp_color = []
    cid = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] == marker_color or comp_id[r][c] != -1:
                continue
            base = grid[r][c]
            q = deque([(r, c)])
            comp_id[r][c] = cid
            while q:
                x, y = q.popleft()
                for nx, ny in neighbors4(x, y):
                    if comp_id[nx][ny] == -1 and grid[nx][ny] == base:
                        comp_id[nx][ny] = cid
                        q.append((nx, ny))
            comp_color.append(base)
            cid += 1
    marker_counts = [0] * cid
    for r, c in color_positions[marker_color]:
        seen = []
        for nr, nc in neighbors4(r, c):
            k = comp_id[nr][nc]
            if k != -1 and k not in seen:
                seen.append(k)
        if not seen:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        k = comp_id[nr][nc]
                        if k != -1 and k not in seen:
                            seen.append(k)
        if seen:
            marker_counts[seen[0]] += 1
    best = max(range(cid), key=lambda k: marker_counts[k])
    return [[comp_color[best]]]

