def solve(grid):
    from collections import Counter, defaultdict, deque
    H, W = len(grid), len(grid[0])
    def crop_horizontal(g):
        m = len(g) // 2
        return g[:m], g[m:]
    def crop_vertical(g):
        m = len(g[0]) // 2
        left = [row[:m] for row in g]
        right = [row[m:] for row in g]
        return left, right
    def dominant_color(sub):
        cnt = Counter()
        for row in sub:
            cnt.update(row)
        return cnt.most_common(1)[0][0]
    def non_bg_count(sub, bg):
        return sum(v != bg for row in sub for v in row)
    def extract_objects(sub, bg):
        h, w = len(sub), len(sub[0])
        seen = [[False] * w for _ in range(h)]
        objs = []
        for r in range(h):
            for c in range(w):
                if seen[r][c] or sub[r][c] == bg:
                    continue
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y, sub[x][y]))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and not seen[nx][ny] and sub[nx][ny] != bg:
                            seen[nx][ny] = True
                            q.append((nx, ny))
                minr = min(x for x, y, v in cells)
                maxr = max(x for x, y, v in cells)
                minc = min(y for x, y, v in cells)
                maxc = max(y for x, y, v in cells)
                rel_cells = [(x - minr, y - minc, v) for x, y, v in cells]
                color_counts = Counter(v for _, _, v in rel_cells)
                maxcnt = max(color_counts.values())
                dominant_inside = min(c for c, k in color_counts.items() if k == maxcnt)
                marker_pos = defaultdict(set)
                for rr, cc, v in rel_cells:
                    if v != dominant_inside:
                        marker_pos[v].add((rr, cc))
                objs.append({
                    "h": maxr - minr + 1,
                    "w": maxc - minc + 1,
                    "cells": rel_cells,
                    "marker_pos": dict(marker_pos),
                })
        return objs
    def reconstruct(source, target):
        sh, sw = len(source), len(source[0])
        th, tw = len(target), len(target[0])
        bg_s = dominant_color(source)
        bg_t = dominant_color(target)
        src_objects = extract_objects(source, bg_s)
        target_pos = defaultdict(set)
        all_markers = set()
        for r in range(th):
            for c in range(tw):
                v = target[r][c]
                if v != bg_t:
                    target_pos[v].add((r, c))
                    all_markers.add((r, c, v))
        if not all_markers:
            return [[bg_t] * tw for _ in range(th)]
        candidates = []
        by_marker = defaultdict(list)
        for oid, obj in enumerate(src_objects):
            mp = obj["marker_pos"]
            if not mp:
                continue
            usable_colors = [col for col in mp if len(target_pos[col]) >= len(mp[col])]
            if not usable_colors:
                continue
            anchor = min(usable_colors, key=lambda col: (len(target_pos[col]), len(mp[col])))
            seen_trans = set()
            for tr, tc in target_pos[anchor]:
                for pr, pc in mp[anchor]:
                    dr, dc = tr - pr, tc - pc
                    if (dr, dc) in seen_trans:
                        continue
                    seen_trans.add((dr, dc))
                    if not (0 <= dr and 0 <= dc and dr + obj["h"] <= th and dc + obj["w"] <= tw):
                        continue
                    cover = set()
                    ok = True
                    for col, posset in mp.items():
                        for rr, cc in posset:
                            rr2, cc2 = rr + dr, cc + dc
                            if (rr2, cc2) not in target_pos[col]:
                                ok = False
                                break
                            cover.add((rr2, cc2, col))
                        if not ok:
                            break
                    if ok:
                        idx = len(candidates)
                        candidates.append({
                            "oid": oid,
                            "dr": dr,
                            "dc": dc,
                            "cover": cover,
                        })
                        for m in cover:
                            by_marker[m].append(idx)
        if not candidates:
            return None
        all_markers = set(all_markers)
        def backtrack(remaining, used):
            if not remaining:
                return []
            chosen_marker = None
            chosen_options = None
            for m in remaining:
                opts = []
                for idx in by_marker.get(m, []):
                    cand = candidates[idx]
                    if cand["oid"] in used:
                        continue
                    if not cand["cover"].issubset(remaining):
                        continue
                    opts.append(idx)
                if not opts:
                    return None
                if chosen_options is None or len(opts) < len(chosen_options):
                    chosen_marker = m
                    chosen_options = opts
            chosen_options.sort(key=lambda idx: -len(candidates[idx]["cover"]))
            for idx in chosen_options:
                cand = candidates[idx]
                res = backtrack(remaining - cand["cover"], used | {cand["oid"]})
                if res is not None:
                    return [idx] + res
            return None
        picked = backtrack(all_markers, set())
        if picked is None:
            return None
        out = [[bg_t] * tw for _ in range(th)]
        for idx in picked:
            cand = candidates[idx]
            obj = src_objects[cand["oid"]]
            dr, dc = cand["dr"], cand["dc"]
            for rr, cc, v in obj["cells"]:
                out[dr + rr][dc + cc] = v
        return out
    attempts = []
    if H % 2 == 0:
        a, b = crop_horizontal(grid)
        attempts.append(reconstruct(a, b))
        attempts.append(reconstruct(b, a))
    if W % 2 == 0:
        a, b = crop_vertical(grid)
        attempts.append(reconstruct(a, b))
        attempts.append(reconstruct(b, a))
    for ans in attempts:
        if ans is not None:
            return ans
    return [row[:] for row in grid]

