    def mark_segment_vertical(c, start, end):
        if not (0 <= c < w) or start > end:
            return
        for r in range(start, end + 1):
            if min(r - start, end - r) % 2 == 0:
                out[r][c] = 5
    mark_segment_horizontal(r1, c1 + 2, c2 - 2)
    mark_segment_horizontal(r2, c1 + 2, c2 - 2)
    mark_segment_vertical(c1, r1 + 2, r2 - 2)
    mark_segment_vertical(c2, r1 + 2, r2 - 2)
    return out

