        seen = [[False] * W for _ in range(H)]
        comps = []
        for r in range(H):
            for c in range(W):
                if grid[r][c] == color and not seen[r][c]:
                    q = deque([(r, c)])
                    seen[r][c] = True
                    cells = []
                    while q:
                        x, y = q.popleft()
                        cells.append((x, y))
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < H and 0 <= ny < W and not seen[nx][ny] and grid[nx][ny] == color:
                                seen[nx][ny] = True
                                q.append((nx, ny))
                    comps.append(cells)
        return comps
    candidates = []
    for comp in components_of_color(2):
        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        height = r1 - r0 + 1
        width = c1 - c0 + 1
        row_counts = {}
        col_counts = {}
        for r, c in comp:
            row_counts[r] = row_counts.get(r, 0) + 1
            col_counts[c] = col_counts.get(c, 0) + 1
        full_rows = [r for r in range(r0, r1 + 1) if row_counts.get(r, 0) == width]
        full_cols = [c for c in range(c0, c1 + 1) if col_counts.get(c, 0) == height]
        if full_cols and (not full_rows or height > width):
            for c in full_cols:
                candidates.append(("v", c, r0, r1))
        else:
            for r in full_rows:
                candidates.append(("h", r, c0, c1))
    out = [row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            if out[r][c] == 5:
                out[r][c] = 0
    for comp in components_of_color(5):
        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        cr0, cr1 = min(rs), max(rs)
        cc0, cc1 = min(cs), max(cs)
        best = None
        best_score = None
        for cand in candidates:
            typ, pos, a0, a1 = cand
            if typ == "v":
                overlap = min(cr1, a1) - max(cr0, a0) + 1
                if overlap <= 0:
                    continue
                dist = min(abs(c - pos) for r, c in comp)
                score = (dist,)
            else:
                overlap = min(cc1, a1) - max(cc0, a0) + 1
                if overlap <= 0:
                    continue
                dist = min(abs(r - pos) for r, c in comp)
                score = (dist,)
            if best_score is None or score < best_score:
                best_score = score
                best = cand
        if best is None:
            continue
        typ, pos, a0, a1 = best
        for r, c in comp:
            if typ == "v":
                nr, nc = r, 2 * pos - c
            else:
                nr, nc = 2 * pos - r, c
            if 0 <= nr < H and 0 <= nc < W:
                out[nr][nc] = 5
    return out

def solve(grid):
    from collections import Counter
    h = len(grid)
    w = len(grid[0]) if h else 0
    counts = Counter()
    first_pos = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                counts[v] += 1
                if v not in first_pos:
                    first_pos[v] = (r, c)
    if not counts:
        return []
    filler = max(counts, key=lambda v: (counts[v], -first_pos[v][0], -first_pos[v][1]))
    others = [v for v in counts if v != filler]
    others.sort(key=lambda v: (-counts[v], first_pos[v]))
    return [[v] for v in others]

def solve(grid):
    counts = {}
    for row in grid:
        for val in row:
            if val != 0:
                counts[val] = counts.get(val, 0) + 1
    sorted_vals = sorted(counts.keys(), key=lambda v: (-counts[v], -v))
    return [[v] for v in sorted_vals]

def solve(grid):
    H, W = len(grid), len(grid[0])
    zeros = [(i, j) for i in range(H) for j in range(W) if grid[i][j] == 0]
    if not zeros:
        return [row[:] for row in grid]
    rmin = min(i for i, _ in zeros)
    rmax = max(i for i, _ in zeros)
    cmin = min(j for _, j in zeros)
    cmax = max(j for _, j in zeros)
    best = None
    best_score = None
    for p in range(1, H + 1):
        for q in range(1, W + 1):
            reps = {}
            ok = True
            for i in range(H):
                for j in range(W):
                    v = grid[i][j]
                    if v == 0:
                        continue
                    key = (i % p, j % q)
                    if key in reps:
                        if reps[key] != v:
                            ok = False
                            break
                    else:
                        reps[key] = v
                if not ok:
                    break
            if not ok:
                continue
            if not all((i % p, j % q) in reps for i, j in zeros):
                continue
            score = (p * q, p, q)
            if best is None or score < best_score:
                best = (p, q, reps)
                best_score = score
    p, q, reps = best
    out = []
    for i in range(rmin, rmax + 1):
        row = []
        for j in range(cmin, cmax + 1):
            row.append(reps[(i % p, j % q)])
        out.append(row)
    return out

def solve(grid):
    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]
    visited = [[False] * w for _ in range(h)]
    def neighbors(r, c):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                yield nr, nc
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                cells = []
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for nr, nc in neighbors(cr, cc):
                        if grid[nr][nc] != 0 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                rows = [x for x, _ in cells]
                cols = [y for _, y in cells]
                min_c, max_c = min(cols), max(cols)
                max_r = max(rows)
                colors = {grid[x][y] for x, y in cells}
                k = len(colors)
                for rr in range(max_r + 1, min(h, max_r + 1 + k)):
                    for cc in range(min_c, max_c + 1):
                        if out[rr][cc] == 0:
                            out[rr][cc] = 3
    return out

def solve(grid):
    row = grid[0]
    k = sum(1 for v in row if v != 0)
    n = 5 * k if k > 0 else 5
    out = [[0 for _ in range(n)] for _ in range(n)]
    for r in range(n):
